
CREATE TABLE "CLIENTE" (
  "ID_CLIENTE" int PRIMARY KEY,
  "codigo_postal" varchar,
  "ciudad" varchar,
  "calle" varchar,
  "numero_exterior" varchar,
  "colonia" varchar
);

CREATE TABLE "CLIENTE_TELEFONO" (
  "ID_CLIENTE" int,
  "telefono" varchar,
  PRIMARY KEY ("ID_CLIENTE", "telefono")
);

CREATE TABLE "POLIZA" (
  "NUM_POLIZA" varchar PRIMARY KEY,
  "ID_CLIENTE" int NOT NULL
);

CREATE TABLE "COBERTURA" (
  "ID_COBERTURA" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "descripcion" varchar
);

CREATE TABLE "POLIZA_COBERTURA" (
  "NUM_POLIZA" varchar,
  "ID_COBERTURA" int,
  PRIMARY KEY ("NUM_POLIZA", "ID_COBERTURA")
);

CREATE TABLE "ACCIDENTE" (
  "ID_ACCIDENTE" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fecha" TIMESTAMP
);

CREATE TABLE "VEHICULO" (
  "MATRICULA" varchar PRIMARY KEY,
  "tipo_vehiculo" varchar
);

CREATE TABLE "VEHICULO_ACCIDENTE" (
  "MATRICULA" varchar,
  "ID_ACCIDENTE" int,
  PRIMARY KEY ("MATRICULA", "ID_ACCIDENTE")
);

CREATE TABLE "AUTOMOVIL" (
  "MATRICULA" varchar PRIMARY KEY,
  "num_puertas" int,
  "tipo_transmision" varchar
);

CREATE TABLE "MOTOCICLETA" (
  "MATRICULA" varchar PRIMARY KEY,
  "cilindrada_cc" int,
  "tipo_manillar" varchar
);

CREATE TABLE "TALLER" (
  "RFC_TALLER" varchar PRIMARY KEY,
  "nombre" varchar
);

CREATE TABLE "REPARACION" (
  "FOLIO_REPARACION" varchar PRIMARY KEY,
  "descripcion" varchar
);

CREATE TABLE "REPARA" (
  "MATRICULA" varchar,
  "RFC_TALLER" varchar,
  "FOLIO_REPARACION" varchar,
  PRIMARY KEY ("MATRICULA", "RFC_TALLER", "FOLIO_REPARACION")
);

CREATE TABLE "RECLAMACION" (
  "ID_ACCIDENTE" int,
  "NUM_POLIZA" varchar,
  "NUM_DE_PAGO" varchar,
  PRIMARY KEY ("ID_ACCIDENTE", "NUM_POLIZA", "NUM_DE_PAGO")
);

CREATE TABLE "PAGO_RECLAMACION" (
  "ID_ACCIDENTE" int,
  "NUM_POLIZA" varchar,
  "NUM_DE_PAGO" varchar,
  "ID_PAGO_REC" INT GENERATED BY DEFAULT AS IDENTITY,
  "monto" decimal,
  PRIMARY KEY ("ID_ACCIDENTE", "NUM_POLIZA", "NUM_DE_PAGO", "ID_PAGO_REC")
);

ALTER TABLE "CLIENTE_TELEFONO" ADD FOREIGN KEY ("ID_CLIENTE") REFERENCES "CLIENTE" ("ID_CLIENTE") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "POLIZA" ADD FOREIGN KEY ("ID_CLIENTE") REFERENCES "CLIENTE" ("ID_CLIENTE") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "POLIZA_COBERTURA" ADD FOREIGN KEY ("NUM_POLIZA") REFERENCES "POLIZA" ("NUM_POLIZA") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "POLIZA_COBERTURA" ADD FOREIGN KEY ("ID_COBERTURA") REFERENCES "COBERTURA" ("ID_COBERTURA") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "VEHICULO_ACCIDENTE" ADD FOREIGN KEY ("MATRICULA") REFERENCES "VEHICULO" ("MATRICULA") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "VEHICULO_ACCIDENTE" ADD FOREIGN KEY ("ID_ACCIDENTE") REFERENCES "ACCIDENTE" ("ID_ACCIDENTE") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "AUTOMOVIL" ADD FOREIGN KEY ("MATRICULA") REFERENCES "VEHICULO" ("MATRICULA") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "MOTOCICLETA" ADD FOREIGN KEY ("MATRICULA") REFERENCES "VEHICULO" ("MATRICULA") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "REPARA" ADD FOREIGN KEY ("MATRICULA") REFERENCES "VEHICULO" ("MATRICULA") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "REPARA" ADD FOREIGN KEY ("RFC_TALLER") REFERENCES "TALLER" ("RFC_TALLER") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "REPARA" ADD FOREIGN KEY ("FOLIO_REPARACION") REFERENCES "REPARACION" ("FOLIO_REPARACION") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "RECLAMACION" ADD FOREIGN KEY ("ID_ACCIDENTE") REFERENCES "ACCIDENTE" ("ID_ACCIDENTE") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "RECLAMACION" ADD FOREIGN KEY ("NUM_POLIZA") REFERENCES "POLIZA" ("NUM_POLIZA") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "PAGO_RECLAMACION" ADD FOREIGN KEY ("ID_ACCIDENTE", "NUM_POLIZA", "NUM_DE_PAGO") REFERENCES "RECLAMACION" ("ID_ACCIDENTE", "NUM_POLIZA", "NUM_DE_PAGO") DEFERRABLE INITIALLY IMMEDIATE;